"""Disposable owned partials, generated bytes and mocked CDN wire responses."""
from contextlib import contextmanager
import hashlib
import io
import threading
from pathlib import Path
from urllib.error import HTTPError
from urllib.parse import urlsplit

import pytest

from creation_lib.mod_manager.download_queue import DownloadFailure, DownloadPaused, DownloadQueue
from creation_lib.mod_manager.library import Library
from creation_lib.mod_manager.nexus import NexusClient, parse_nxm
from creation_lib.mod_manager.paths import ManagerError
from .test_nexus import LINK, Response


class CDN:
    def __init__(self, payload=None):
        self.payload = payload or b"generated-fixture" * (200_000)
        self.etag = '"fixture-v1"'
        self.requests, self.resolves = [], []
        self.mode = "normal"
        self.expected_md5 = True

    def __call__(self, request, timeout):
        self.requests.append(request)
        assert urlsplit(request.full_url).hostname == "files.nexusmods.com"
        assert request.get_header("Apikey") is None
        offset = int(request.get_header("Range").split("=")[1].split("-")[0]) if request.get_header("Range") else 0
        if self.mode == "restart":
            offset = 0
        payload = self.payload[offset:]
        headers = {"Content-Length": str(len(payload)), "ETag": self.etag}
        status = 206 if offset else 200
        if self.mode == "unknown":
            headers.pop("Content-Length")
        if offset:
            headers["Content-Range"] = f"bytes {offset}-{len(self.payload) - 1}/{len(self.payload)}"
        if self.mode == "unknown" and offset == len(self.payload):
            status = 416
            headers["Content-Range"] = f"bytes */{len(self.payload)}"
        if self.mode == "bad-range":
            headers["Content-Range"] = f"bytes 0-{len(self.payload) - 1}/{len(self.payload)}"
        if self.mode == "empty-range":
            payload = b""
            headers.update({"Content-Length": "0", "Content-Range": f"bytes {offset}-{offset - 1}/{offset}"})
        if self.mode == "shorter-total":
            payload = payload[:32]
            headers.update({"Content-Length": "32", "Content-Range": f"bytes {offset}-{offset + 31}/{offset + 32}"})
        if self.mode == "truncated":
            payload = payload[:1024**2]
        if self.mode == "oversized":
            headers["Content-Length"] = str(9 * 1024**3)
        response = Response(payload, headers)
        response.status = status
        return response

    def client(self):
        client = NexusClient("fixture-session-secret", transport=self)
        client.user = {"user_id": 42, "name": "Fixture", "premium": True}
        def resolve(link):
            self.resolves.append(link)
            # Tokens and the signed URL never reach the persisted record.
            return {"file_name": "Fixture.zip", "version": "1.2", "md5": hashlib.md5(self.payload, usedforsecurity=False).hexdigest() if self.expected_md5 else ""}, "https://files.nexusmods.com/Fixture.zip?ticket=fixture-private-ticket"
        client.resolve = resolve
        return client


def paused(tmp_path, cdn=None):
    library = Library(tmp_path / "library", create=True)
    queue = DownloadQueue(library)
    identifier = queue.enqueue(parse_nxm(LINK))
    client, cancel = (cdn or CDN()).client(), threading.Event()
    with pytest.raises(DownloadPaused):
        queue.run(identifier, client, parse_nxm(LINK), cancel, lambda *args: cancel.set())
    assert queue.get(identifier)["state"] == "paused" and not library.downloads()
    return library, queue, identifier, client


def test_pause_restart_range_resume_repeated_identity_and_no_credentials_on_disk(tmp_path):
    library, queue, identifier, client = paused(tmp_path)
    cdn = client._transport
    checkpoint = queue.get(identifier)["record"]["bytes"]
    assert 0 < checkpoint < len(cdn.payload)
    reopened = DownloadQueue(Library(library.root))
    assert reopened.enqueue(parse_nxm(LINK)) == identifier
    path = Path(reopened.run(identifier, client))
    assert path.read_bytes() == cdn.payload
    assert cdn.requests[-1].get_header("Range") == f"bytes={checkpoint}-"
    assert cdn.requests[-1].get_header("If-range") == cdn.etag
    assert reopened.get(identifier)["state"] == "complete" and len(library.downloads()) == 1
    requests = len(cdn.requests)
    assert reopened.run(identifier, client) == str(path) and len(cdn.requests) == requests
    persisted = library.database.read_bytes()
    assert not any(secret in persisted for secret in (b"fixture-session-secret", b"fixture-key", b"fixture-private-ticket", b"https://"))
    reopened.remove(identifier)
    assert not reopened.records() and path.read_bytes() == cdn.payload and len(library.downloads()) == 1
    assert reopened.enqueue(parse_nxm(LINK)) == identifier
    assert reopened.run(identifier, client) == str(path) and len(cdn.requests) == requests
    assert len(library.downloads()) == 1


@pytest.mark.parametrize("mode", ["restart", "weak"])
def test_nonmatching_or_weak_validator_restarts_without_appending(tmp_path, mode):
    cdn = CDN()
    if mode == "weak":
        cdn.etag = 'W/"fixture-v1"'
    _, queue, identifier, client = paused(tmp_path, cdn)
    cdn.mode = "restart" if mode == "restart" else "normal"
    path = Path(queue.run(identifier, client))
    assert path.read_bytes() == cdn.payload
    if mode == "weak":
        assert cdn.requests[-1].get_header("Range") is None


@pytest.mark.parametrize("mode", ["bad-range", "truncated", "oversized", "empty-range", "shorter-total"])
def test_invalid_cdn_response_retains_owned_checkpoint_without_registration(tmp_path, mode):
    cdn = CDN()
    cdn.expected_md5 = False
    library, queue, identifier, client = paused(tmp_path, cdn)
    client._transport.mode = mode
    with pytest.raises(DownloadFailure):
        queue.run(identifier, client)
    assert queue.get(identifier)["state"] == "failed" and not library.downloads()
    assert (library.root / "downloads" / ".partials" / (identifier + ".part")).is_file()


def test_partial_mutation_rejected_and_verified_crash_tail_is_discarded(tmp_path):
    _, queue, identifier, client = paused(tmp_path)
    partial, _ = queue._paths(queue.get(identifier))
    original = partial.read_bytes()
    partial.write_bytes(original + b"uncommitted crash tail")
    assert Path(queue.run(identifier, client)).read_bytes() == client._transport.payload
    other = tmp_path / "other"
    other.mkdir()
    _, queue, identifier, client = paused(other)
    partial, _ = queue._paths(queue.get(identifier))
    partial.write_bytes(b"changed prefix" + partial.read_bytes()[14:])
    with pytest.raises(DownloadFailure, match="partial data changed"):
        queue.run(identifier, client)


def test_finalizing_rename_interruption_recovers_without_network_or_duplicate_payload(tmp_path, monkeypatch):
    library = Library(tmp_path / "library", create=True)
    queue, cdn = DownloadQueue(library), CDN()
    identifier = queue.enqueue(parse_nxm(LINK))
    def interrupted(job, partial, folder, cancel=None):
        folder.mkdir()
        partial.rename(folder / job["record"]["filename"])
        raise SystemExit("generated process interruption")
    monkeypatch.setattr(queue, "_finish", interrupted)
    client = cdn.client()
    with pytest.raises(SystemExit):
        queue.run(identifier, client)
    assert queue.get(identifier)["state"] == "finalizing" and not library.downloads()
    requests = len(cdn.requests)
    reopened = DownloadQueue(Library(library.root))
    path = Path(reopened.run(identifier, client))
    assert path.read_bytes() == cdn.payload and len(cdn.requests) == requests
    assert len(library.downloads()) == 1 and reopened.get(identifier)["state"] == "complete"


def test_late_cancel_rolls_back_download_registration_and_keeps_recoverable_bytes(tmp_path, monkeypatch):
    library = Library(tmp_path / "library", create=True)
    queue, client = DownloadQueue(library), CDN().client()
    identifier = queue.enqueue(parse_nxm(LINK))
    cancel, original = threading.Event(), library._db
    monkeypatch.setattr(queue, "_checkpoint", lambda name: cancel.set() if name == "before-commit" else None)
    with pytest.raises(DownloadPaused):
        queue.run(identifier, client, cancel=cancel)
    with original() as connection:
        assert connection.execute("SELECT count(*) FROM downloads").fetchone()[0] == 0
    assert queue.get(identifier)["state"] == "finalizing"
    monkeypatch.setattr(library, "_db", original)
    path = Path(queue.run(identifier, client))
    assert path.read_bytes() == client._transport.payload


def test_completed_archive_change_does_not_silently_reuse_or_delete_it(tmp_path):
    library, queue, identifier, client = paused(tmp_path)
    path = Path(queue.run(identifier, client))
    path.write_bytes(b"user changed owned archive")
    with pytest.raises(ManagerError, match="Completed download changed"):
        queue.run(identifier, client)
    assert path.read_bytes() == b"user changed owned archive"


def test_failed_partial_removal_preserves_resumable_metadata(tmp_path, monkeypatch):
    _, queue, identifier, _ = paused(tmp_path)
    partial, _ = queue._paths(queue.get(identifier))
    original = Path.unlink
    def denied(path, *args, **kwargs):
        if path == partial:
            raise PermissionError("generated removal failure")
        return original(path, *args, **kwargs)
    monkeypatch.setattr(Path, "unlink", denied)
    with pytest.raises(PermissionError):
        queue.remove(identifier)
    assert queue.get(identifier)["state"] == "paused" and partial.is_file()


def test_cancel_after_receiving_all_bytes_resumes_finalization_without_invalid_empty_range(tmp_path):
    library = Library(tmp_path / "library", create=True)
    queue, cdn, cancel = DownloadQueue(library), CDN(), threading.Event()
    identifier = queue.enqueue(parse_nxm(LINK))
    client = cdn.client()
    def progress(fraction, detail):
        if fraction == 1:
            cancel.set()
    with pytest.raises(DownloadPaused):
        queue.run(identifier, client, cancel=cancel, progress=progress)
    requests = len(cdn.requests)
    assert Path(queue.run(identifier, client)).read_bytes() == cdn.payload
    assert len(cdn.requests) == requests


def test_exception_after_real_commit_keeps_registered_archive_in_place(tmp_path, monkeypatch):
    library = Library(tmp_path / "library", create=True)
    queue, client = DownloadQueue(library), CDN().client()
    identifier = queue.enqueue(parse_nxm(LINK))
    original = library._db
    @contextmanager
    def db():
        committing_download = False
        with original() as connection:
            yield connection
            committing_download = bool(connection.execute("SELECT count(*) FROM downloads").fetchone()[0])
        if committing_download:
            raise SystemExit("generated interruption after durable commit")
    monkeypatch.setattr(library, "_db", db)
    with pytest.raises(SystemExit):
        queue.run(identifier, client)
    monkeypatch.setattr(library, "_db", original)
    assert queue.get(identifier)["state"] == "complete"
    assert Path(library.downloads()[0]["path"]).read_bytes() == client._transport.payload
    assert Path(queue.run(identifier, client)).read_bytes() == client._transport.payload


def test_controller_finishes_local_receipt_offline_even_when_selected_game_differs(tmp_path, monkeypatch):
    from creation_lib.mod_manager.controller import ManagerController
    from .test_controller import finish
    library = Library(tmp_path / "library", create=True)
    queue, cdn = DownloadQueue(library), CDN()
    identifier = queue.enqueue(parse_nxm(LINK))
    def interrupted(*args, **kwargs):
        raise SystemExit("generated interruption before rename")
    monkeypatch.setattr(queue, "_finish", interrupted)
    with pytest.raises(SystemExit):
        queue.run(identifier, cdn.client())
    manager = ManagerController()
    try:
        manager.library = Library(library.root)
        manager.nexus_game = "skyrim"
        manager.refresh()
        assert manager.nexus_client is None and manager.download_local_recovery(manager.download_jobs[0])
        manager.resume_download(identifier)
        finish(manager)
        assert Path(manager.download_records[0]["path"]).read_bytes() == cdn.payload
    finally:
        manager.cleanup()


def test_unknown_length_pause_at_eof_recovers_only_from_exact_strong_validator_proof(tmp_path):
    library = Library(tmp_path / "library", create=True)
    queue, cdn, cancel = DownloadQueue(library), CDN(), threading.Event()
    cdn.mode = "unknown"
    identifier = queue.enqueue(parse_nxm(LINK))
    client = cdn.client()
    def progress(fraction, detail):
        if detail == f"Downloading {len(cdn.payload):,} bytes":
            cancel.set()
    with pytest.raises(DownloadPaused):
        queue.run(identifier, client, cancel=cancel, progress=progress)
    assert queue.get(identifier)["record"]["total"] == 0
    assert Path(queue.run(identifier, client)).read_bytes() == cdn.payload
    assert cdn.requests[-1].get_header("Range") == f"bytes={len(cdn.payload)}-"


@pytest.mark.parametrize("proof", ["exact", "wrong-total", "changed-etag", "missing-etag", "weak-etag", "malformed-range"])
def test_http_error_416_requires_exact_strong_eof_proof_without_md5(tmp_path, proof):
    class ErrorCDN(CDN):
        def __init__(self):
            super().__init__()
            self.mode, self.proof = "unknown", proof
            self.expected_md5 = False
            self.error_bodies = []

        def __call__(self, request, timeout):
            if not request.get_header("Range"):
                return super().__call__(request, timeout)
            self.requests.append(request)
            assert request.get_header("Range") == f"bytes={len(self.payload)}-"
            assert request.get_header("If-range") == self.etag
            assert request.get_header("Apikey") is None
            headers = {"Content-Range": f"bytes */{len(self.payload)}", "ETag": self.etag}
            if self.proof == "wrong-total":
                headers["Content-Range"] = f"bytes */{len(self.payload) - 1}"
            elif self.proof == "changed-etag":
                headers["ETag"] = '"different-file"'
            elif self.proof == "missing-etag":
                del headers["ETag"]
            elif self.proof == "weak-etag":
                headers["ETag"] = "W/" + self.etag
            elif self.proof == "malformed-range":
                headers["Content-Range"] = "bytes */-1"
            body = io.BytesIO(b"generated inert error response")
            self.error_bodies.append(body)
            raise HTTPError(request.full_url, 416, "generated EOF response", headers, body)

    library = Library(tmp_path / "library", create=True)
    queue, cdn, cancel = DownloadQueue(library), ErrorCDN(), threading.Event()
    identifier, client = queue.enqueue(parse_nxm(LINK)), cdn.client()

    def progress(fraction, detail):
        if detail == f"Downloading {len(cdn.payload):,} bytes":
            cancel.set()

    with pytest.raises(DownloadPaused):
        queue.run(identifier, client, cancel=cancel, progress=progress)
    checkpoint = queue.get(identifier)["record"]
    assert checkpoint["bytes"] == len(cdn.payload) and checkpoint["total"] == 0 and not checkpoint["md5"]
    partial, _ = queue._paths(queue.get(identifier))
    if proof != "exact":
        with pytest.raises(DownloadFailure, match="EOF response does not prove"):
            queue.run(identifier, client)
        assert queue.get(identifier)["state"] == "failed" and not library.downloads()
        assert queue.get(identifier)["record"] == checkpoint and partial.read_bytes() == cdn.payload
        assert cdn.error_bodies[-1].closed
        # A rejected proof must leave the prefix usable on a subsequent valid response.
        cdn.proof = "exact"
        queue = DownloadQueue(Library(library.root))
    target = Path(queue.run(identifier, client))
    assert target.read_bytes() == cdn.payload and not partial.exists()
    assert queue.get(identifier)["state"] == "complete" and len(library.downloads()) == 1
    assert all(body.closed for body in cdn.error_bodies)
